var i=[{title:`De ce contează obiceiurile`,text:`Forța, capacitatea cardiovasculară și îndemânarea de mișcare se dezvoltă prin practică repetată. Un antrenament care arată grozav pe hârtie este inutil dacă este prea lung, incomod sau neplăcut de repetat. Asta face din frecvență și respectare o parte a proiectării programului, nu doar o chestiune de motivație.`},{title:`Leagă antrenamentul de un semnal`,text:`Leagă antrenamentul de ceva ce se întâmplă deja sau de o programare fixă: „După muncă, luni și joi, fac sesiunea de 25 de minute”. Pregătește din timp hainele, spațiul sau echipamentul. Fă primul pas minuscul, de exemplu să îți pui pantofii și să începi o încălzire de cinci minute, ca să nu depinzi de entuziasm.`},{title:`Ai o sesiune minimă`,text:`Într-o zi ocupată, o variantă de genuflexiune, o împingere sau o tragere și o plimbare scurtă pot păstra obiceiul în viață. Minimul nu este un înlocuitor permanent al antrenamentului progresiv. Rolul lui este să oprească o zi ratată să devină mai multe săptămâni ratate. Notează ce ai făcut de fapt și nu înregistra un antrenament scurtat ca fiind complet.`},{title:`Gestionează calm eșecurile`,text:`O sesiune ratată nu șterge adaptările tale anterioare. Reia cu următorul antrenament planificat și nu dubla volumul de muncă pentru a „plăti” antrenamentul ratat. După boală, oboseală severă sau o pauză lungă, scade intensitatea și volumul până când toleranța ta obișnuită revine.`},{title:`Verifică-ți mediul`,text:`Somnul slab, un drum complicat până la sală, echipamentul la care nu ajungi și sesiunile prea lungi pot submina constanța. Rezolvarea lor poate ajuta mai mult decât găsirea unui exercițiu nou. Faptul că îți place antrenamentul și că îl alegi singur face rutina mai ușor de păstrat.`},{title:`Folosind TrainUp`,text:`Setează în Profil un număr realist de zile de antrenament și zilele preferate, apoi introdu spațiul și echipamentul, ca planul să aleagă doar exerciții potrivite. Mementourile de antrenament din Panou pot fi semnalul tău. Istoricul arată antrenamentele din această săptămână și totalul, iar progresul se numără pe multe săptămâni, deci nu ai nevoie de o serie perfectă.`}];var t=[{label:`CDC: obiceiuri și planificarea activității`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`},{label:`Recomandările OMS privind activitatea`,url:`https://www.who.int/europe/news-room/fact-sheets/item/physical-activity`}];var n={sections:i,sources:t};export{n as default,i as sections,t as sources};